{
 "format": "mmk3-presets-1",
 "presets": [
  {
   "name": "Default",
   "description": "What the firmware starts with: Play and Stop send MIDI Start and Stop, every other button sends NI's Control Change numbers, pads 1-16 play notes 36-51 (General MIDI drums), encoder CC 7, touch strip CC 1, MIDI channel 1, local lighting on.",
   "cfg": ""
  },
  {
   "name": "Maschine-like modes",
   "description": "The controller's own functions, with a message on the screen: Pad Mode (drum notes), Keyboard (C3 on pad 1) with 24 scales (Shift + Keyboard / Pad Mode), Chords with five chord types (Shift + Chords / Step), Fixed Vel, Shift + Fixed Vel = 16 Velocities, Shift + Volume / Swing = velocity curve (kept when unplugged), Shift + Mute = panic, the arrows transpose (Shift: an octave), Pitch / Mod / Perform / Notes = strip modes, Volume / Swing / Tempo = what the encoder turns, Favorites / Browser / Project = Program Change, Tap = tap tempo (Shift: MIDI clock out), Note Repeat = arp / repeat (Shift: rate) with Follow = pattern, Auto = octaves, Lock = latch, Mute / Solo = mute / solo pads. The buttons used here no longer send their CCs; everything else is as in Default.",
   "cfg": ""
  },
  {
   "name": "Groove Rider 2",
   "description": "Tried on an iPad: pads (Trigger, Keys), strip (cutoff), encoder (Last Knob Control), Solo / Mute (send A / B throws). Pads 1-16 = notes 36-51, strip = CC 74, encoder = relative CC 20 (its touch sensor sends nothing, or the app learns that instead of the turn; push = CC 8), Solo / Mute = CC 91 / 92, Erase = CC 120. In the app: Midi In Device = the Mikro, Single channel 1. The transport cannot be mapped there.",
   "cfg": ""
  },
  {
   "name": "Korg Gadget 3 (draft)",
   "description": "Draft, from Korg's manual and forum posts, not tried. Pads 36-51 into the track whose MIDI button is lit; Play / Stop / Rec / Restart / Tap = CC 3 / 119 / 2 / 118 / 117 (press only) for Gadget's Transport CC settings, which you enter there; encoder CC 7 (level), strip CC 1. Encoder push and touch send nothing. Keep channel 16 free.",
   "cfg": ""
  },
  {
   "name": "Cubasis 3 (draft)",
   "description": "Draft, from Steinberg's help and forum posts, not tried. Pads 36-51 (GM kits). Buttons send CC 102-114 once per press (Play, Stop, Rec, Restart, Left, Right, Mute, Solo, Select, Follow, Tap, Browser, Favorites): learn each one in Cubasis (Selected Track Mode on); do not declare the port Mackie/HUI. Encoder CC 20 (volume, Catch-Up), strip CC 21 (pan).",
   "cfg": ""
  },
  {
   "name": "FL Studio Mobile (draft)",
   "description": "Draft, from Image-Line's manual and forum posts, not tried. Pads 48-63 (its drum pads start at note 48). Play / Stop / Restart / Rec = MMC play / stop / rewind / record (its only transport input). Group..Tempo, Mute, Solo = CC 20-31 toggles to learn onto parameters. Encoder CC 102, push CC 103, strip CC 1. Touch sends nothing (learn would grab it).",
   "cfg": ""
  },
  {
   "name": "GarageBand (draft)",
   "description": "Draft, from Apple's guide and old forum posts, not tried. GarageBand has no MIDI learn: pads 36-51 (GM drum kits; use 48 for keyboard sounds), strip = mod wheel CC 1, encoder = volume CC 7, Note Repeat = sustain CC 64 while held, Play / Stop / Rec = MMC (a forum claim; transport is otherwise only by keyboard). Turn MPE off. Everything else sends nothing.",
   "cfg": ""
  },
  {
   "name": "Custom A",
   "description": "for the tests",
   "cfg": ""
  }
 ]
}
